const store = $getWorkflowStaticData('global');
const res = $input.first().json;
const status = res.status ?? 'error';

// ── Watch health, EDGE-triggered ────────────────────────────────────────────
// A site that 404s, blocks us, or switches to a JS-rendered page makes this
// watch permanently blind while looking perfectly healthy in n8n. Worth one
// push — but only on the transition, never once per poll.
if (status === 'error') {
  const wasBroken = Boolean(store.broken);
  store.broken = true;
  if (wasBroken) { return []; }
  return [{ json: {
    alert: true,
    detail: res.detail ?? '',
    url: res.url ?? '',
    fingerprint: '',
    added: [],
    added_count: 0,
  } }];
}
store.broken = false;

// 'baseline' is the first sight of a page: recorded, deliberately silent.
if (status !== 'ok' || !res.changed) { return []; }

// ── Something was published ─────────────────────────────────────────────────
return [{ json: {
  alert: false,
  url: res.url,
  title: res.title ?? '',
  fingerprint: res.fingerprint,
  added: res.added ?? [],
  added_count: res.added_count ?? 0,
  truncated: Boolean(res.truncated),
  removed_count: res.removed_count ?? 0,
} }];
